SELECT 'gongkao', '基础工程', 'kp-xc-eng-basic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基础工程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "基础工程问题是工程问题的核心模型，工作量=效率×时间三个量之间的关系是所有工程题的基础。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、知识要点"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：工作总量 = 工作效率 × 工作时间"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设工作总量为特殊值法：设总量为各时间的最小公倍数，简化计算"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "效率单位：通常设为\"份\"，如甲的效率为1/10表示甲每天完成总量的1/10"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "多者合作：总效率 = 各人效率之和"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "工程问题与行程问题本质相同，都是效率×时间=总量的模型"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、解题方法"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设总量法：设工作总量为各完成时间的最小公倍数"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设效率法：直接设各人的效率为未知量"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比例法：效率比确定后，用比例关系求时间"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "方程法：根据题意列方程求解"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "工作总量和工作效率搞混"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "设总量时没有取最小公倍数，导致分数计算复杂"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "多人合作时效率相加出错"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "基础工程是所有工程题的原型，必须熟练。建议先掌握设总量法，再练习设效率法。"}]}]}]}$$ AS jsonb), NULL, '数量关系-工程问题-基础工程的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "工程问题", "基础工程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
